INSERT INTO `menu_item_translations` (`id`, `menu_item_id`, `locale`, `name`, `description`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'Fresh Spring Rolls', 'Crispy spring rolls filled with fresh vegetables and herbs, served with sweet chili sauce', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(2, 1, 'km', 'នំបញ្ចុំ', 'នំបញ្ចុំគ្រឿងសម្រាប់ដាក់បន្លែស្រស់ និង ស្លឹកឈូក ជាមួយទឹកជ្រលក់ផ្អែម', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(3, 2, 'en', 'Chicken Satay', 'Grilled chicken skewers marinated in aromatic spices, served with peanut sauce', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(4, 2, 'km', 'សាច់មាន់អាំង', 'សាច់មាន់អាំងជាមួយគ្រឿងទេស ផ្តល់ជាមួយទឹកជ្រលក់សណ្តែកដី', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(5, 3, 'en', 'Cambodian Fish Cakes', 'Traditional fish cakes made with fresh river fish and aromatic herbs', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(6, 3, 'km', 'អាម៉ុកត្រី', 'អាម៉ុកត្រីប្រពៃណីធ្វើពីត្រីស្រស់ និង ស្លឹកឈូក', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(7, 4, 'en', 'Green Papaya Salad', 'Fresh and tangy salad with shredded green papaya, tomatoes, and lime dressing', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(8, 4, 'km', 'បុកល្ហុង', 'សាឡាត់ល្ហុងបៃតងស្រស់ជាមួយប៉េងប៉ោះ និង ទឹកក្រូចឆ្មា', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(9, 5, 'en', 'Cambodian Beef Salad', 'Tender beef slices with fresh herbs, vegetables and tangy lime dressing', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(10, 5, 'km', 'ភ្លាសាច់គោ', 'សាច់គោជាមួយស្លឹកឈូកស្រស់ និង ទឹកក្រូចឆ្មា', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(11, 6, 'en', 'Mixed Appetizer Platter', 'A selection of our finest appetizers perfect for sharing', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(12, 6, 'km', 'ចានម្ហូបបំប៉នចម្រុះ', 'ម្ហូបបំប៉នពិសេសៗសម្រាប់ចែករំលែក', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(13, 7, 'en', 'Traditional Khmer Noodle Soup', 'Authentic Cambodian noodle soup with rich broth and fresh herbs', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
(14, 7, 'km', 'គុយទាវខ្មែរ', 'គុយទាវខ្មែរប្រពៃណីជាមួយទឹកស៊ុបឈុំ និង ស្លឹកឈូក', '2025-12-12 07:33:49', '2025-12-12 07:33:49'),
